function autoAdvance(s,setOperation){if(!isLab(s.type,s.step))return false;init(s);const h=s.hl,p=s.ph;if(s.step===1){switch(s.operation){case 0:setOperation(1);h.tared=true;return true;case 1:h.tared=true;act(s,'weigh');setOperation(2);h.stir=true;return true;case 2:if(!h.dissolved[h.salt])return true;setOperation(3);return true;case 3:h.stir=false;h.barOut[h.salt]=true;h.transferred[h.salt]=true;h.rinses[h.salt]=3;act(s,'next');setOperation(s.operation);return true;case 4:h.pk=true;h.micro=true;h.condition=true;h.filled=true;h.mixed=true;setOperation(5);return true;case 5:h.condition=true;h.filled=true;h.mixed=true;return false}}else{switch(s.operation){case 0:setOperation(1);return true;case 1:p.cal7=true;p.rinsed=true;setOperation(2);return true;case 2:p.cal4=true;p.rinsed=true;p.medium='sample';p.clock=0;p.stable=false;setOperation(3);return true;case 3:act(s,'record');setOperation(4);return true;case 4:return false}}return false}
